program='''def transform(grid):
    height, width = len(grid), len(grid[0])
    ones = {(r, c) for r in range(height) for c in range(width) if grid[r][c] == 8}
    masks = {
        1: ((0, 0), (0, 1), (1, 0), (1, 1)),
        2: ((0, 1), (1, 0), (1, 1)),  # L missing its upper-left cell
        3: ((0, 0), (0, 1), (1, 1)),  # L missing its lower-left cell
        4: ((0, 0), (1, 0), (1, 1)),  # L missing its upper-right cell
    }
    points = sorted(ones)
    point_id = {point: i for i, point in enumerate(points)}
    full = (1 << len(points)) - 1
    placements = []
    by_point = [[] for _ in points]

    for r in range(height - 1):
        for c in range(width - 1):
            for color, mask in masks.items():
                cells = tuple((r + dr, c + dc) for dr, dc in mask)
                if all(cell in point_id for cell in cells):
                    bits = sum(1 << point_id[cell] for cell in cells)
                    index = len(placements)
                    placements.append((color, bits, cells))
                    for cell in cells:
                        by_point[point_id[cell]].append(index)

    failed = set()
    def solve(remaining):
        if not remaining:
            return ()
        if remaining in failed:
            return None
        best_options = None
        bits = remaining
        while bits:
            low = bits & -bits
            point = low.bit_length() - 1
            options = [i for i in by_point[point] if placements[i][1] & remaining == placements[i][1]]
            if best_options is None or len(options) < len(best_options):
                best_options = options
                if not options:
                    failed.add(remaining)
                    return None
            bits ^= low
        for index in best_options:
            result = solve(remaining ^ placements[index][1])
            if result is not None:
                return (index,) + result
        failed.add(remaining)
        return None

    chosen = solve(full)
    output = [[0 for _ in range(width)] for _ in range(height)]
    if chosen is not None:
        for index in chosen:
            color, _, cells = placements[index]
            for r, c in cells:
                output[r][c] = color
    return output
'''
